5	use Illuminate\Database\Eloquent\Factories\HasFactory;
6	use Illuminate\Database\Eloquent\Model;
7	use Illuminate\Database\Eloquent\Relations\BelongsTo;
8	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
9	use Illuminate\Database\Eloquent\Relations\HasMany;
10	use Illuminate\Database\Eloquent\SoftDeletes;
11	use Illuminate\Support\Str;
12	use Spatie\Activitylog\Models\Concerns\LogsActivity;
13	use Spatie\Activitylog\Support\LogOptions;
14	
15	/**
16	 * spec/Platform_RBAC_Phase2_Specification.md §4 (v3.0) — category dùng chung toàn nền tảng,
17	 * không extends TenantAwareModel nữa (organization_id vẫn còn cột, nhưng nullable/không còn
18	 * global-scope — xem migration 2026_07_13_000003). Biên tập viên phụ trách theo category qua
19	 * bảng post_category_editors (§4.2), không theo tổ chức.
20	 */
21	class PostCategory extends Model
22	{
23	    use HasFactory;
24	    use SoftDeletes;
25	    use LogsActivity;
26	
27	    protected $table = 'post_categories';
28	
29	    public function getActivitylogOptions(): LogOptions
30	    {
31	        return LogOptions::defaults()
32	            ->logFillable()
33	            ->logOnlyDirty()
34	            ->dontLogEmptyChanges();
35	    }
36	
37	    protected $fillable = [
38	        'uuid',
39	        'organization_id',
40	        'parent_id',
41	        'name',
42	        'slug',
43	        'description',
44	        'icon',
45	        'color_hex',
46	        'sort_order',
47	        'is_active',
48	        'created_by',
49	        'updated_by',
50	    ];
51	
52	    protected $casts = [
53	        'is_active'  => 'boolean',
54	        'sort_order' => 'integer',
55	    ];
56	
57	    protected static function booted(): void
58	    {
59	        static::creating(function (self $model): void {
60	            if (empty($model->uuid)) {
61	                $model->uuid = (string) Str::uuid();
62	            }
63	        });
64	    }
65	
66	    public function getRouteKeyName(): string
67	    {
68	        return 'uuid';
69	    }
70	
71	    // ── Relationships ────────────────────────────────────────────────
72	
73	    public function parent(): BelongsTo
74	    {
75	        return $this->belongsTo(PostCategory::class, 'parent_id');
76	    }
77	
78	    public function children(): HasMany
79	    {
80	        return $this->hasMany(PostCategory::class, 'parent_id')->orderBy('sort_order');
81	    }
82	
83	    public function articles(): BelongsToMany
84	    {
85	        return $this->belongsToMany(PostArticle::class, 'post_article_categories', 'category_id', 'article_id')
86	            ->withPivot('is_primary');
87	    }
88	
89	    public function createdBy(): BelongsTo
90	    {
91	        return $this->belongsTo(\App\Models\User::class, 'created_by');
92	    }
93	
94	    public function updatedBy(): BelongsTo
95	    {
96	        return $this->belongsTo(\App\Models\User::class, 'updated_by');
97	    }
98	
99	    /** platform_section_editor được gán phụ trách category này (§4.2). */
100	    public function editors(): BelongsToMany
101	    {
102	        return $this->belongsToMany(\App\Models\User::class, 'post_category_editors', 'post_category_id', 'user_id');
103	    }
104	
105	    // ── Scopes ───────────────────────────────────────────────────────
106	
107	    public function scopeActive($query)
108	    {
109	        return $query->where('is_active', true);
110	    }
111	
112	    public function scopeRoot($query)
113	    {
114	        return $query->whereNull('parent_id');
115	    }
116	
117	    /**
118	     * Cây danh mục gốc + con (active) — KHÔNG còn dùng cho nav/drawer nữa (từ
119	     * spec/Menu_Navigation_Technical_Specification.md Phase 3, nav đọc MenuItem::tree() qua
120	     * View Composer ở Modules/Menu). Vẫn được PublicCategoryController::index() dùng cho
121	     * home.blade.php (x-frontend.promo-bar/cta-band) — 2 section trang chủ độc lập với nav,
122	     * xem spec §2/§9.
123	     */
124	    public static function navTree(): \Illuminate\Support\Collection
125	    {
126	        return static::active()->root()
127	            ->with(['children' => fn ($q) => $q->active()->orderBy('sort_order')])
128	            ->orderBy('sort_order')
129	            ->get();
130	    }
131	
132	    /**
133	     * Cây phẳng (pre-order, depth-annotated) từ 1 cây đã dựng sẵn (vd
134	     * Features\CategoryManagement\Queries\GetCategoryTreeHandler) — dùng cho <select> đơn
135	     * (parent_id), không lồng được HTML như cây thật. $excludeSubtreeRootId loại bỏ node đó VÀ
136	     * toàn bộ hậu duệ của nó — dùng khi sửa 1 category, tránh chọn con/cháu làm cha của chính nó
137	     * (cycle).
138	     *
139	     * @param \Illuminate\Support\Collection<int, self> $tree
140	     * @return array<int, array{category: self, depth: int}>
141	     */
142	    public static function flatten(\Illuminate\Support\Collection $tree, ?int $excludeSubtreeRootId = null): array
143	    {
144	        $flat = [];
145	
146	        $walk = function (\Illuminate\Support\Collection $nodes, int $depth) use (&$walk, &$flat, $excludeSubtreeRootId): void {
147	            foreach ($nodes as $node) {
148	                if ($node->id === $excludeSubtreeRootId) {
149	                    continue; // bỏ cả node này VÀ mọi hậu duệ (không đệ quy tiếp vào $node->children)
150	                }
151	                $flat[] = ['category' => $node, 'depth' => $depth];
152	                $walk($node->children, $depth + 1);
153	            }
154	        };
155	
156	        $walk($tree, 0);
157	
158	        return $flat;
159	    }
160	
161	    /** Id của node $id và toàn bộ hậu duệ — dùng để chặn cycle ở validation (parent_id). */
162	    public static function subtreeIds(\Illuminate\Support\Collection $tree, int $id): array
163	    {
164	        $ids = [];
165	
166	        $walk = function (\Illuminate\Support\Collection $nodes, bool $collecting) use (&$walk, &$ids, $id): void {
167	            foreach ($nodes as $node) {
168	                $inSubtree = $collecting || $node->id === $id;
169	                if ($inSubtree) {
170	                    $ids[] = $node->id;
171	                }
172	                $walk($node->children, $inSubtree);
173	            }
174	        };
175	
176	        $walk($tree, false);
177	
178	        return $ids;
179	    }
180	}
